#if defined(C3HT_EU_BUILD)
#include "eu_internal.h"
#include <esp_ota_ops.h>
#include <esp_partition.h>
#include <esp_image_format.h>
#include <mbedtls/ecdsa.h>
#include <mbedtls/sha256.h>
#include "c3ht_eu_pubkeys.h"   // generated by python/c3ht_eu_pre.py (public keys only)

/*
 * Signed OTA (DESIGN.md section 4). Not built on Arduino Update (it holds back
 * the first 16 bytes and sets the boot partition inside end()).
 *  - HTTP body -> esp_ota_begin(OTA_WITH_SEQUENTIAL_WRITES) / esp_ota_write
 *    (sector-wise erase, no multi-second erase in the async_tcp task);
 *  - after the last byte, in loop(): esp_ota_end (IDF structure + SHA check),
 *    esp_image_verify -> image_len, trailer = last 128 bytes of the upload,
 *    checks, SHA-256(image[0:image_len] || trailer[0:64]) read back from
 *    flash, ECDSA P-256 verify against compiled/USB-enrolled keys;
 *  - only then esp_ota_set_boot_partition. On any failure the slot's first
 *    sector is erased so no bootable header remains.
 * The options block after the image is not signed and is treated as untrusted
 * input (src/options.cpp, EU branch).
 */

#define QUOTE_(x) #x
#define STR_(x) QUOTE_(x)
static const char OWN_TARGET[] = STR_(TARGET_NAME);
static const char EU_PREFIX[] = "C3HTEU_";
static const uint8_t MARKER[] = {0xBE, 0xEF, 0xCA, 0xFE, 'C', '3', 'H', 'T', 'E', 'U', '_'};

#define TRAILER_LEN 128
#define TRAILER_HDR 64
#define UPLOAD_MAX_MS (5UL * 60UL * 1000UL)
#define UPLOAD_IDLE_MS (30UL * 1000UL)

struct __attribute__((packed)) Trailer {
    char magic[8];
    uint16_t version;
    uint16_t length;
    uint32_t image_len;
    uint32_t security_version;
    uint32_t flags;
    uint8_t key_id[8];
    char target[32];
    uint8_t sig[64];
};
static_assert(sizeof(Trailer) == TRAILER_LEN, "trailer size");

static EuOtaState st = OTA_IDLE;
static char msg[96] = "";
static esp_ota_handle_t handle = 0;
static const esp_partition_t *part = nullptr;
static size_t total = 0, received = 0;
static uint32_t startMs = 0, lastDataMs = 0;
static bool allowOther = false;
// streaming marker scan
static uint8_t mpos = 0;
static bool mCapturing = false, mFound = false;
static char mTarget[32];
static uint8_t mLen = 0;
static size_t mOffset = 0;
// async_tcp task (write/finish) and loop task (timeouts/verify) both touch the state
static SemaphoreHandle_t mtx = nullptr;
struct Lock {
    Lock() { if (!mtx) mtx = xSemaphoreCreateMutex(); xSemaphoreTake(mtx, portMAX_DELAY); }
    ~Lock() { xSemaphoreGive(mtx); }
};

struct UserKey { char magic[4]; uint8_t point[65]; uint8_t crc[2]; };

static bool loadUserKey(uint8_t point[65], uint8_t id[8])
{
    UserKey k;
    if (!euCredPartRead(EU_CRED_SLOT_USERKEY, (uint8_t *)&k, sizeof(k))) return false;
    if (memcmp(k.magic, "C3UK", 4) != 0) return false;
    uint16_t crc = euCrc16((const uint8_t *)&k, 4 + 65);
    if (k.crc[0] != (crc >> 8) || k.crc[1] != (crc & 0xff)) return false;
    memcpy(point, k.point, 65);
    if (id) {
        uint8_t h[32];
        euSha256(point, 65, h);
        memcpy(id, h, 8);
    }
    return true;
}

bool euUserKeyPresent()
{
    uint8_t p[65];
    return loadUserKey(p, nullptr);
}

int euOtaKeyCount() { return C3HT_EU_PUBKEY_COUNT + (euUserKeyPresent() ? 1 : 0); }
bool euOtaEnabled() { return euOtaKeyCount() > 0; }

void euOtaKeyIds(char *out, size_t len)
{
    out[0] = 0;
    for (int i = 0; i < C3HT_EU_PUBKEY_COUNT; i++) {
        char hex[17];
        euHex(C3HT_EU_PUBKEYS[i].id, 8, hex);
        if (out[0]) strlcat(out, ",", len);
        strlcat(out, hex, len);
        if (C3HT_EU_PUBKEYS[i].dev) strlcat(out, "(DEV)", len);
    }
    uint8_t p[65], id[8];
    if (loadUserKey(p, id)) {
        char hex[17];
        euHex(id, 8, hex);
        if (out[0]) strlcat(out, ",", len);
        strlcat(out, hex, len);
        strlcat(out, "(USER)", len);
    }
}

static bool pointValid(const uint8_t point[65])
{
    mbedtls_ecp_group grp;
    mbedtls_ecp_point Q;
    mbedtls_ecp_group_init(&grp);
    mbedtls_ecp_point_init(&Q);
    bool ok = point[0] == 0x04 && mbedtls_ecp_group_load(&grp, MBEDTLS_ECP_DP_SECP256R1) == 0 &&
              mbedtls_ecp_point_read_binary(&grp, &Q, point, 65) == 0 && mbedtls_ecp_check_pubkey(&grp, &Q) == 0;
    mbedtls_ecp_point_free(&Q);
    mbedtls_ecp_group_free(&grp);
    return ok;
}

const char *euUserKeyAdd(const char *hex130)
{
    UserKey k;
    memcpy(k.magic, "C3UK", 4);
    if (!euUnhex(hex130, k.point, 65)) return "need 130 hex characters (uncompressed P-256 point 04||X||Y)";
    if (!pointValid(k.point)) return "not a valid P-256 point";
    uint16_t crc = euCrc16((const uint8_t *)&k, 4 + 65);
    k.crc[0] = crc >> 8;
    k.crc[1] = crc & 0xff;
    if (!euCredPartWrite(EU_CRED_SLOT_USERKEY, (const uint8_t *)&k, sizeof(k))) return "write failed";
    euLogEvent(EV_KEY_ADDED, 0, true);
    return nullptr;
}

bool euUserKeyRemove()
{
    uint8_t ff[sizeof(UserKey)];
    memset(ff, 0xff, sizeof(ff));
    bool ok = euCredPartWrite(EU_CRED_SLOT_USERKEY, ff, sizeof(ff));
    if (ok) euLogEvent(EV_KEY_REMOVED, 0, true);
    return ok;
}

uint32_t euEffectiveMinSv()
{
    uint32_t s = euStoredMinSv();
    return s > C3HT_EU_SECURITY_VERSION ? s : C3HT_EU_SECURITY_VERSION;
}

EuOtaState euOtaState() { return st; }
const char *euOtaMessage() { return msg; }
uint32_t euOtaProgress() { return received; }
uint32_t euOtaTotal() { return total; }

static void fail(const char *why, uint16_t code)
{
    if (handle) {
        esp_ota_abort(handle);
        handle = 0;
    }
    // No bootable header left behind, but never erase the slot that is already
    // selected for the next boot (an accepted update, or the running image).
    if (part && part != esp_ota_get_boot_partition() && part != esp_ota_get_running_partition())
        esp_partition_erase_range(part, 0, 4096);
    strlcpy(msg, why, sizeof(msg));
    st = OTA_FAILED;
    euLogEvent(EV_UPDATE_REJECT, code, true);
}

void euOtaAbort(const char *why)
{
    Lock l;
    if (st == OTA_RECEIVING || st == OTA_VERIFYING) fail(why, 99);
}

const char *euOtaBegin(size_t len, bool allowOtherEuTarget)
{
    Lock l;
    if (st == OTA_RECEIVING || st == OTA_VERIFYING) return "an update is already in progress";
    // After an accepted update the next-update slot (counted from the RUNNING
    // partition) is the slot that was just made bootable: a second upload would
    // overwrite the verified image with unverified bytes before the reboot.
    if (st == OTA_DONE) return "update accepted; rebooting";
    const esp_partition_t *bootp = esp_ota_get_boot_partition();
    if (bootp && bootp != esp_ota_get_running_partition()) return "an accepted update is pending; reboot first";
    if (!euOtaEnabled()) return "OTA disabled in this build (no public key); update over USB";
    part = esp_ota_get_next_update_partition(nullptr);
    if (!part) return "no OTA partition";
    if (part == bootp) {   // defence in depth: never write into the boot slot
        part = nullptr;
        return "no free OTA partition";
    }
    if (len < 64 * 1024 || len > part->size) return "bad image size";
    if (esp_ota_begin(part, OTA_WITH_SEQUENTIAL_WRITES, &handle) != ESP_OK) {
        handle = 0;
        return "flash error";
    }
    total = len;
    received = 0;
    startMs = lastDataMs = millis();
    allowOther = allowOtherEuTarget;
    mpos = 0;
    mCapturing = mFound = false;
    mLen = 0;
    mOffset = 0;
    msg[0] = 0;
    st = OTA_RECEIVING;
    return nullptr;
}

static void scan(const uint8_t *d, size_t len, size_t base)
{
    for (size_t i = 0; i < len && !mFound; i++) {
        uint8_t b = d[i];
        if (mCapturing) {
            if (b == 0) {
                mTarget[mLen] = 0;
                mFound = true;
            } else if (mLen < sizeof(mTarget) - 1 && b > 0x20 && b < 0x7f) {
                mTarget[mLen++] = (char)b;
            } else {
                mCapturing = false;
                mpos = 0;
            }
            continue;
        }
        if (b == MARKER[mpos]) {
            if (++mpos == sizeof(MARKER)) {
                mCapturing = true;
                memcpy(mTarget, EU_PREFIX, 7);
                mLen = 7;
                mOffset = base + i + 1 - sizeof(MARKER);
                mpos = 0;
            }
        } else {
            mpos = (b == MARKER[0]) ? 1 : 0;
        }
    }
}

const char *euOtaWrite(const uint8_t *data, size_t len, size_t index)
{
    Lock l;
    if (st != OTA_RECEIVING) return "not receiving";
    if (index != received || received + len > total) {
        fail("out-of-order data", 1);
        return msg;
    }
    if (esp_ota_write(handle, data, len) != ESP_OK) {
        fail(received == 0 ? "not an ESP32 application image" : "flash write failed", 2);
        return msg;
    }
    scan(data, len, received);
    received += len;
    lastDataMs = millis();
    return nullptr;
}

void euOtaFinish()
{
    Lock l;
    if (st != OTA_RECEIVING) return;
    if (received != total) {
        fail("incomplete upload", 3);
        return;
    }
    st = OTA_VERIFYING;
    strlcpy(msg, "verifying signature", sizeof(msg));
}

static bool findKey(const uint8_t id[8], uint8_t point[65], bool *isDev)
{
    for (int i = 0; i < C3HT_EU_PUBKEY_COUNT; i++) {
        if (memcmp(C3HT_EU_PUBKEYS[i].id, id, 8) == 0) {
            memcpy(point, C3HT_EU_PUBKEYS[i].point, 65);
            *isDev = C3HT_EU_PUBKEYS[i].dev;
            return true;
        }
    }
    uint8_t uid[8];
    if (loadUserKey(point, uid) && memcmp(uid, id, 8) == 0) {
        *isDev = false;
        return true;
    }
    return false;
}

static bool ecdsaVerify(const uint8_t point[65], const uint8_t hash[32], const uint8_t sig[64])
{
    mbedtls_ecp_group grp;
    mbedtls_ecp_point Q;
    mbedtls_mpi r, s;
    mbedtls_ecp_group_init(&grp);
    mbedtls_ecp_point_init(&Q);
    mbedtls_mpi_init(&r);
    mbedtls_mpi_init(&s);
    bool ok = mbedtls_ecp_group_load(&grp, MBEDTLS_ECP_DP_SECP256R1) == 0 &&
              mbedtls_ecp_point_read_binary(&grp, &Q, point, 65) == 0 &&
              mbedtls_ecp_check_pubkey(&grp, &Q) == 0 &&
              mbedtls_mpi_read_binary(&r, sig, 32) == 0 &&
              mbedtls_mpi_read_binary(&s, sig + 32, 32) == 0 &&
              mbedtls_ecdsa_verify(&grp, hash, 32, &Q, &r, &s) == 0;
    mbedtls_mpi_free(&r);
    mbedtls_mpi_free(&s);
    mbedtls_ecp_point_free(&Q);
    mbedtls_ecp_group_free(&grp);
    return ok;
}

static void verifyNow()
{
    esp_err_t e = esp_ota_end(handle);
    handle = 0;
    if (e != ESP_OK) return fail("image structure/checksum invalid", 10);

    esp_partition_pos_t pos = {part->address, part->size};
    esp_image_metadata_t meta;
    if (esp_image_verify(ESP_IMAGE_VERIFY_SILENT, &pos, &meta) != ESP_OK) return fail("image verify failed", 11);

    Trailer t;
    if (total < TRAILER_LEN || esp_partition_read(part, total - TRAILER_LEN, &t, sizeof(t)) != ESP_OK)
        return fail("read error", 12);
    if (memcmp(t.magic, "C3HTSIG1", 8) != 0) return fail("unsigned image (no C3HTSIG1 trailer)", 13);
    if (t.version != 1 || t.length != TRAILER_LEN) return fail("unsupported trailer version", 14);
    if (t.image_len != meta.image_len || t.image_len > total - TRAILER_LEN) return fail("image length mismatch", 15);
    size_t tl = strnlen(t.target, sizeof(t.target));
    if (tl == sizeof(t.target)) return fail("bad target field", 16);
    for (size_t i = tl; i < sizeof(t.target); i++)
        if (t.target[i]) return fail("bad target field", 16);
    if (strncmp(t.target, EU_PREFIX, 7) != 0) return fail("not a C3HT EU image", 17);
    if (strcmp(t.target, OWN_TARGET) != 0 && !allowOther) return fail("image is for another goggle type", 18);
    if (!mFound || mOffset >= t.image_len || strcmp(mTarget, t.target) != 0)
        return fail("target marker in image does not match signature block", 19);
    if (t.security_version < euEffectiveMinSv()) return fail("older security version (rollback refused)", 20);
    uint8_t point[65];
    bool isDev = false;
    if (!findKey(t.key_id, point, &isDev)) return fail("signed with an unknown key", 21);

    static uint8_t buf[4096];
    mbedtls_sha256_context ctx;
    mbedtls_sha256_init(&ctx);
    mbedtls_sha256_starts_ret(&ctx, 0);
    for (size_t off = 0; off < t.image_len; off += sizeof(buf)) {
        size_t n = t.image_len - off < sizeof(buf) ? t.image_len - off : sizeof(buf);
        if (esp_partition_read(part, off, buf, n) != ESP_OK) {
            mbedtls_sha256_free(&ctx);
            return fail("read error", 22);
        }
        mbedtls_sha256_update_ret(&ctx, buf, n);
        if ((off & 0x3FFFF) == 0) delay(1);   // feed the idle task / watchdog
    }
    mbedtls_sha256_update_ret(&ctx, (const uint8_t *)&t, TRAILER_HDR);
    uint8_t hash[32];
    mbedtls_sha256_finish_ret(&ctx, hash);
    mbedtls_sha256_free(&ctx);
    if (!ecdsaVerify(point, hash, t.sig)) return fail("bad signature", 23);

    if (esp_ota_set_boot_partition(part) != ESP_OK) return fail("could not select new image", 24);
    snprintf(msg, sizeof(msg), "update accepted (%s, security version %u%s); rebooting", t.target,
             (unsigned)t.security_version, isDev ? ", DEV key" : "");
    st = OTA_DONE;
    euLogEvent(EV_UPDATE_OK, (uint16_t)t.security_version, true);
    extern unsigned long rebootTime;
    rebootTime = millis() + 2000;
}

void euOtaLoop(uint32_t now)
{
    if (st != OTA_RECEIVING && st != OTA_VERIFYING) return;
    Lock l;
    now = millis();   // the caller's timestamp may predate a write in the async task
    if (st == OTA_RECEIVING) {
        if (now - startMs > UPLOAD_MAX_MS) fail("upload took longer than 5 minutes", 4);
        else if (now - lastDataMs > UPLOAD_IDLE_MS) fail("upload stalled", 5);
    } else if (st == OTA_VERIFYING) {
        verifyNow();
    }
}
#endif
